namespace sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Client.Models;

public sealed class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public DateTimeOffset? EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> Updates { get; init; }
}

public sealed class StatusUpdate
{
    public required DateTimeOffset Timestamp { get; init; }
    public required string Description { get; init; }
    public required string Location { get; init; }
}

using sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Client.Models;

namespace sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Client.Models;

namespace sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Client.Services;

/// <summary>
/// Client-side implementation that calls the server API.
/// Used when the component runs in WebAssembly.
/// </summary>
public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Client.Models;
using sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Client.Services;

namespace sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 1, 17, 0, 0, TimeSpan.FromHours(-5)),
            Updates =
            [
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 20, 9, 0, 0, TimeSpan.FromHours(-5)),
                    Description = "Package picked up",
                    Location = "New York, NY"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 21, 14, 30, 0, TimeSpan.FromHours(-5)),
                    Description = "Departed sorting facility",
                    Location = "Newark, NJ"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 23, 6, 15, 0, TimeSpan.FromHours(-5)),
                    Description = "Arrived at regional hub",
                    Location = "Chicago, IL"
                }
            ]
        },
        ["TRK-2002"] = new Shipment
        {
            TrackingNumber = "TRK-2002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 18, 12, 0, 0, TimeSpan.FromHours(-7)),
            Updates =
            [
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 15, 8, 0, 0, TimeSpan.FromHours(-7)),
                    Description = "Package picked up",
                    Location = "Seattle, WA"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 17, 11, 0, 0, TimeSpan.FromHours(-7)),
                    Description = "Out for delivery",
                    Location = "San Francisco, CA"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 17, 14, 22, 0, TimeSpan.FromHours(-7)),
                    Description = "Delivered — signed by J. Smith",
                    Location = "San Francisco, CA"
                }
            ]
        },
        ["TRK-3003"] = new Shipment
        {
            TrackingNumber = "TRK-3003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 5, 18, 0, 0, TimeSpan.FromHours(-5)),
            Updates =
            [
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 23, 16, 45, 0, TimeSpan.FromHours(-5)),
                    Description = "Label created, awaiting pickup",
                    Location = "Dallas, TX"
                }
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        Seeds.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Client.Models
@using sv_1ae262e8bd3a4a7aa7ceed5ea2a088bf.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h3>Shipment Tracker</h3>

@if (isLoading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@errorMessage</p>
        <button class="btn btn-outline-danger btn-sm mt-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @shipment.Status</p>
            <p><strong>Location:</strong> @shipment.Location</p>
            @if (shipment.EstimatedDelivery.HasValue)
            {
                <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("f")</p>
            }
        </div>
    </div>

    @if (shipment.Updates.Count > 0)
    {
        <h5>Status Updates</h5>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Description</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in shipment.Updates)
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Description</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? shipment;
    private bool isLoading;
    private string? errorMessage;

    private CancellationTokenSource? cts;
    private string loadedTrackingNumber = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(TrackingNumber, loadedTrackingNumber, StringComparison.OrdinalIgnoreCase)
            && !isLoading && errorMessage is null)
        {
            return;
        }

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        CancelPending();

        cts = new CancellationTokenSource();
        loadedTrackingNumber = TrackingNumber;
        shipment = null;
        errorMessage = null;
        isLoading = true;

        try
        {
            shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
        }
        catch (OperationCanceledException)
        {
            // Navigation changed or component disposed — nothing to show.
            return;
        }
        catch (TaskCanceledException)
        {
            Logger.LogError("Request for shipment {TrackingNumber} timed out", TrackingNumber);
            errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException)
        {
            Logger.LogError("Request for shipment {TrackingNumber} timed out", TrackingNumber);
            errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}", TrackingNumber);
            errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    private void CancelPending()
    {
        cts?.Cancel();
        cts?.Dispose();
        cts = null;
    }

    public void Dispose()
    {
        CancelPending();
    }
}

