            Updates =
            [
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 23, 16, 45, 0, TimeSpan.FromHours(-5)),
                    Description = "Label created, awaiting pickup",
                    Location = "Dallas, TX"
                }
